function generateQuestion(id,rawTier=1,r=Math.random){
 if(!skillById[id]?.playable)throw new Error(`No generator for ${id}`);
 const t=Math.max(1,Math.min(4,Math.round(Number(rawTier)||1)));
 const q=legacy(id,t,r)||extra(id,t,r);
 if(!q)throw new Error(`Missing generator for ${id}`);
 const maybe=r();
 // Sortable temperature, decimal and place-value tiles add a genuinely different puzzle interaction.
 if(['number.negativeIntro','decimals.tenths','number.place2'].includes(id)&&maybe>=.56&&maybe<.74){
   const values=new Set();const div=id==='decimals.tenths'?(t<3?10:100):1;
   const max=id==='number.negativeIntro'?[7,12,20,40][t-1]:id==='number.place2'?[20,99,500,3000][t-1]:div-1;
   const min=id==='number.negativeIntro'?-max:1;
   while(values.size<3)values.add(ri(min,max,r));
   const sorted=[...values].sort((a,b)=>a-b).map(x=>prettyMath(x/div));
   q.mode='order';q.stem=id==='number.negativeIntro'?'Tap the temperatures from coldest to warmest.':id==='decimals.tenths'?'Tap the decimal numbers in ascending order.':'Tap these numbers from smallest to largest.';
   q.tokens=shuffle(sorted,r);q.answer=sorted.join('|');q.visual={kind:'math',display:'Smallest  →  Largest'};
   q.explanation=`The correct order is ${sorted.join(' < ')}.`;
 }
 // Different puzzle interactions ask learners to *construct* an answer, not just recognise one.
 // Only fractions between zero and one with a manageable denominator use the build-a-bar control.
 const fractionMatch=/^(-?\d+)\/(\d+)$/.exec(q.answer);
 const canBuild=!!fractionMatch&&Number(fractionMatch[1])>=0&&Number(fractionMatch[1])<=Number(fractionMatch[2])&&[2,3,4,5,6,8,10,12].includes(Number(fractionMatch[2]));
 if(q.mode==='order')return q;
 if(q.numberLine&&Math.abs(q.visual.move)<=12&&maybe<.30){q.mode='stepper';}
 else if(q.numberLine&&maybe<.68){q.mode='slider';}
 else if(canBuild&&maybe<.34){q.mode='fractionbuild';}
 else if(q.expression&&q.choices&&maybe>.72&&maybe<.88&&/^[-\d.\/]+$/.test(q.answer)){
   // Replace a binary yes/no guess with a constructed correction to Dr Bones’ slip.
   const actual=q.answer, wrong=pick(q.choices.filter(x=>!isCorrect({...q,mode:'choice',answer:actual},x.value)),r);
   if(wrong){q.mode='repair';q.stem=`Dr Bones wrote “${q.expression} = ${prettyMath(wrong.value)}” in his notebook. Can you check the calculation?`;
     q.explanation=`The correct result is ${prettyMath(actual)}. ${q.explanation}`;q.visual={kind:'math',display:`${q.expression} = ${prettyMath(wrong.value)} ?`};}
   else q.mode='type';
 }
 else if(maybe<.67&&!(id==='count.to20'&&t===1)&&/^[-\d.\/]+$/.test(q.answer)){q.mode='type';}
 else{q.mode='choice';}

 return q;
}
const EMPTY_SKILL=()=>({attempts:0,correct:0,independent:0,tier:1,unlockedTier:1,history:[],tierProgress:{},lastSeen:0,nextReview:0});
function tierStats(record,tier){const p=record?.tierProgress?.[String(tier)]||{attempts:0,independent:0,history:[]};const recent=p.history?.slice(-10)||[];return {attempts:p.attempts||0,independent:p.independent||0,recentIndependent:recent.filter(x=>x.independent).length,recentCount:recent.length,ready:(p.attempts||0)>=10&&recent.length>=10&&recent.filter(x=>x.independent).length>=7};}
function recordAttempt(record,{correct,hintUsed,tier=1,mode='choice',now=Date.now()}){
 const p={...EMPTY_SKILL(),...record},independent=Boolean(correct&&!hintUsed),entry={correct:!!correct,independent,tier,mode,at:now};
 const history=[...p.history,entry].slice(-100),tierProgress={...p.tierProgress},prevTier=tierProgress[String(tier)]||{attempts:0,independent:0,history:[]};
 tierProgress[String(tier)]={attempts:prevTier.attempts+1,independent:prevTier.independent+(independent?1:0),history:[...(prevTier.history||[]),entry].slice(-30)};
 const priorUnlocked=p.unlockedTier||p.tier||1;const stats=tierStats({tierProgress},tier);
 const unlockedTier=stats.ready&&tier===priorUnlocked?Math.min(4,priorUnlocked+1):priorUnlocked;
 const tierNow=unlockedTier>priorUnlocked?unlockedTier:Math.min(Math.max(p.tier||1,1),unlockedTier);
 const recent=history.slice(-8);const success=recent.filter(x=>x.independent).length;
 const reviewDays=success>=6?3:success>=4?1:0;
 return {...p,attempts:p.attempts+1,correct:p.correct+(correct?1:0),independent:p.independent+(independent?1:0),tier:tierNow,unlockedTier,tierProgress,history,lastSeen:now,nextReview:now+reviewDays*86400000,newUnlock:unlockedTier>priorUnlocked};
}
function suggestSkill(progress,preference='mixed',r=Math.random){
 const allowed=playableSkills.filter(s=>preference==='mixed'||s.zone===preference);
 return allowed.map(s=>{const p=progress?.[s.id]||EMPTY_SKILL();const due=p.attempts>0&&p.nextReview<=Date.now();return {s,score:(p.attempts===0?2:0)+(due?3:0)+(p.unlockedTier<4?1:0)+r()};}).sort((a,b)=>b.score-a.score)[0]?.s||playableSkills[0];
}
function parseNumber(value){
 const raw=String(value).trim().replace(/[−–]/g,'-').replace(/\s/g,'');if(!raw)return null;
 if(/^[-+]?\d+(?:\.\d+)?\/[-+]?\d+(?:\.\d+)?$/.test(raw)){const [a,b]=raw.split('/').map(Number);return b? a/b:null;}
 if(/^[-+]?\d+(?:\.\d+)?$/.test(raw))return Number(raw);
 return null;
}
function isCorrect(q,response){
 if(q.mode==='verify')return String(response)===q.answer;
 if(typeof response!=='string'&&typeof response!=='number')return false;
 const a=parseNumber(q.answer),b=parseNumber(response);
 if(a!==null&&b!==null)return Math.abs(a-b)<1e-8;
 return String(response).trim().toLowerCase()===String(q.answer).trim().toLowerCase();
}

