function researchRewardAt(awardIndex=0){
 const n=Math.max(0,Math.floor(Number(awardIndex)||0));
 const newIndex=n-Math.floor(n/4);
 const index=n%4===3?newIndex-1:newIndex;
 return researchRewards[((index%researchRewards.length)+researchRewards.length)%researchRewards.length];
}
