// teaching.js
// Small, transparent mathematical models, for a child to explore without being assessed.
// This is developmental educational content rather than a substitute for professional teaching.
const workshops={
 valley:{title:'Make a number bond',idea:'Two groups can make a total. You can rearrange them and keep the same total.',prompt:'Add or remove eggs from either nest.',type:'bond',steps:['Count each nest separately.','Join the two groups to find the total.','Try swapping their sizes: does the total change?']},
 grove:{title:'Grow an array',idea:'Multiplication counts equal groups. An array shows the number of rows and columns.',prompt:'Change the rows and columns of fern plants.',type:'array',steps:['Count the rows and plants in each row.','Multiply rows × columns.','Swap rows and columns and check the total.']},
 lagoon:{title:'Fraction folding',idea:'Equivalent fractions name the same amount of a whole, even if the pieces are smaller.',prompt:'Split the same half into more equal pieces.',type:'fraction',steps:['Start with half of the bar shaded.','Split every piece into the same number of smaller pieces.','Check that the shaded part has not changed.']},
 cavern:{title:'Percent explorer',idea:'Percent means per hundred. A 10 × 10 grid helps connect a percentage to a quantity.',prompt:'Colour more or fewer squares in the hundred-grid.',type:'percent',steps:['Ten rows of ten give 100 squares.','Count the shaded squares.','Compare the number shaded with the percentage.']},
 quarry:{title:'Build the enclosure',idea:'Area counts square units inside. Perimeter measures the distance all the way round.',prompt:'Change the width and height of a research enclosure.',type:'rectangle',steps:['Count squares inside for the area.','Walk around the boundary for perimeter.','Look for rectangles with similar area but different perimeter.']},
 ridge:{title:'Research lift',idea:'A positive movement takes you up the number line; a negative movement takes you down.',prompt:'Change how far the lift travels from its starting point.',type:'numberline',steps:['Locate the start at −3.','Positive moves travel right; negative moves left.','Read the finishing position, including its sign.']},
 station:{title:'Keep the equation balanced',idea:'An equation is like balanced scales: do the same operation to both sides to preserve equality.',prompt:'Remove one counter from both sides at a time.',type:'balance',steps:['Begin at x + 3 = 8.','Remove 1 from both sides.','When no extra counters remain, the value of x is visible.']},
 highlands:{title:'Scale the supplies',idea:'A ratio compares amounts. Multiplying both quantities by the same factor keeps the ratio.',prompt:'Choose how many groups of supplies to pack.',type:'ratio',steps:['Look at 2 water bottles for every 3 food packs.','Build several identical groups.','Notice the numbers change but the 2:3 relationship stays.']}
};
const guidance={
 'number.signed':{watch:'Track the direction of the move, not just the size.',misconception:'A negative number is a position, whereas subtracting tells you which operation to perform.'},
 'number.signedSubtract':{watch:'Subtracting a negative goes in the opposite direction to subtracting a positive.',misconception:'A minus operation and a negative sign have different jobs.'},
 'fractions.add':{watch:'Make equal-sized pieces before adding or subtracting.',misconception:'Adding the denominators changes the size of the pieces, so it is not a valid rule.'},
 'fractions.signed':{watch:'First decide whether the fractions are positive or negative. Then find equal-sized pieces.',misconception:'The sign and the denominator are separate things to keep track of.'},
 'fractions.equivalent':{watch:'Scale numerator and denominator together.',misconception:'Doubling just the top number does not give an equivalent fraction.'},
 'algebra.oneStep':{watch:'Undo the operation applied to the unknown.',misconception:'Whatever you do to one side of an equation must also be done to the other.'},
 'algebra.twoStep':{watch:'Undo addition or subtraction first, then multiplication or division.',misconception:'Avoid doing both inverse steps in one leap until the order is familiar.'},
 'multiply.tables':{watch:'Build equal groups rather than trying to remember a fact immediately.',misconception:'Changing the group size changes the total even when the number of groups stays fixed.'},
 'geometry.perimeter':{watch:'Walk round the boundary once.',misconception:'Perimeter measures the border, not the inside area.'}
};
function supportFor(skill,zone){return guidance[skill?.id]||{watch:workshops[zone]?.idea||'Try showing the maths with objects or a drawing.',misconception:'If the method feels confusing, start with a smaller example.'};}
// Exploratory lesson without correctness judging: calculations are derived from controls.
function modelMarkup(zone,a,b){
 const n=(x,low,high)=>Math.max(low,Math.min(high,Math.floor(Number(x)||0)));
 const dots=(k,cls='model-dot')=>Array.from({length:k},()=>`<span class="${cls}" aria-hidden="true"></span>`).join('');
 const controls=(left,right)=>`<div class="workshop-actions"><button class="alt-btn" data-action="lab-minus-a" aria-label="${left} less">${left} −</button><button class="alt-btn" data-action="lab-plus-a" aria-label="${left} more">${left} +</button><button class="alt-btn" data-action="lab-minus-b" aria-label="${right} less">${right} −</button><button class="alt-btn" data-action="lab-plus-b" aria-label="${right} more">${right} +</button></div>`;
 if(zone==='valley'){a=n(a,0,10);b=n(b,0,10);return `<div class="workshop-equation">${a} + ${b} = <strong>${a+b}</strong></div><div class="workshop-nests"><div><small>Nest A</small><div>${dots(a,'egg-dot')}</div></div><div><small>Nest B</small><div>${dots(b,'egg-dot')}</div></div></div>${controls('nest A','nest B')}`;}
 if(zone==='grove'){a=n(a,1,6);b=n(b,1,6);return `<div class="workshop-equation">${a} rows × ${b} plants = <strong>${a*b}</strong></div><div class="array-view" style="--cols:${b}">${dots(a*b,'fern-dot')}</div>${controls('rows','columns')}`;}
 if(zone==='lagoon'){a=n(a,1,4);const k=a;return `<div class="workshop-equation">½ = <strong>${k}/${2*k}</strong></div><div class="fraction-demo"><small>One half</small><div class="fraction-grid" style="--cols:2"><span class="filled"></span><span></span></div><small>The same half, with ${2*k} equal parts</small><div class="fraction-grid" style="--cols:${2*k}">${Array.from({length:2*k},(_,i)=>`<span class="${i<k?'filled':''}"></span>`).join('')}</div></div><div class="workshop-actions"><button class="alt-btn" data-action="lab-minus-a">Fewer pieces</button><button class="alt-btn" data-action="lab-plus-a">More pieces</button></div>`;}
 if(zone==='cavern'){a=n(a,0,10);return `<div class="workshop-equation"><strong>${a*10}%</strong> = ${a*10} out of 100</div><div class="hundred-grid">${Array.from({length:100},(_,i)=>`<span class="${i<a*10?'filled':''}"></span>`).join('')}</div><div class="workshop-actions"><button class="alt-btn" data-action="lab-minus-a">Shade 10 fewer</button><button class="alt-btn" data-action="lab-plus-a">Shade 10 more</button></div>`;}
 if(zone==='quarry'){a=n(a,1,8);b=n(b,1,6);return `<div class="workshop-equation">Area = <strong>${a*b}</strong> squares · Perimeter = <strong>${2*(a+b)}</strong> units</div><div class="rectangle-demo" style="--cols:${a}">${dots(a*b,'area-square')}</div><div class="small muted">${a} units wide × ${b} units tall</div>${controls('width','height')}`;}
 if(zone==='ridge'){a=n(a,-10,10);b=n(b,-10,10);const end=a+b;const min=-20,max=20;return `<div class="workshop-equation">${a<0?'−'+Math.abs(a):a} ${b<0?'−':'+'} ${Math.abs(b)} = <strong>${end<0?'−'+Math.abs(end):end}</strong></div><div class="lab-numberline"><div class="lab-line"></div>${Array.from({length:9},(_,i)=>{const x=-20+i*5;return `<span class="lab-tick" style="left:${(x-min)/(max-min)*100}%"><b>│</b>${x}</span>`;}).join('')}<span class="lab-marker start" style="left:${(a-min)/(max-min)*100}%" title="Starting at ${a}">●</span><span class="lab-marker finish" style="left:${(end-min)/(max-min)*100}%" title="Finishing at ${end}">◆</span></div><div class="small muted">● Starting point · ◆ Finish · move ${b<0?'left':'right'} ${Math.abs(b)}</div>${controls('start','move')}`;}
 if(zone==='station'){a=n(a,0,3);return `<div class="workshop-equation">x ${a?'+ '+a+' ':''}= <strong>${5+a}</strong></div><div class="balance-scales"><div class="balance-pan"><strong>x</strong> ${dots(a,'egg-dot')}<small>left side</small></div><div class="balance-pan">${dots(5+a,'egg-dot')}<small>right side</small></div></div><div class="small muted">Remove 1 from <strong>both</strong> sides. The equation remains balanced.</div><div class="workshop-actions"><button class="alt-btn" data-action="lab-minus-a" ${a===0?'disabled':''}>Remove 1 from both</button><button class="alt-btn" data-action="lab-reset">Start again</button></div>`;}
 if(zone==='highlands'){a=n(a,1,5);return `<div class="workshop-equation">Water : food = <strong>${2*a} : ${3*a}</strong></div><div class="ratio-groups">${Array.from({length:a},()=>`<div class="ratio-pack"><span>💧 💧</span><span>🌿 🌿 🌿</span></div>`).join('')}</div><div class="small muted">${a} complete group${a!==1?'s':''} of 2 water supplies and 3 food supplies.</div><div class="workshop-actions"><button class="alt-btn" data-action="lab-minus-a">Fewer groups</button><button class="alt-btn" data-action="lab-plus-a">More groups</button></div>`;}
 return '';
}
function initialModel(zone){return {a:({valley:3,grove:3,lagoon:2,cavern:4,quarry:4,ridge:-3,station:3,highlands:2})[zone]??2,b:({valley:4,grove:4,lagoon:1,cavern:0,quarry:3,ridge:5,station:8,highlands:3})[zone]??2};}
function adjustModel(zone,control,a,b){
 if(control==='lab-reset')return initialModel(zone);
 const cfg={valley:[[0,10],[0,10]],grove:[[1,6],[1,6]],lagoon:[[1,4],[0,0]],cavern:[[0,10],[0,0]],quarry:[[1,8],[1,6]],ridge:[[-10,10],[-10,10]],station:[[0,3],[0,0]],highlands:[[1,5],[0,0]]}[zone];
 if(!cfg)return {a,b};
 const side=control.endsWith('-b')?'b':'a',delta=control.includes('plus')?1:-1,next={a,b};next[side]=Math.max(cfg[side==='a'?0:1][0],Math.min(cfg[side==='a'?0:1][1],next[side]+delta));return next;
}

// routes.js

// A short, transparent route: warm-up, current skill, related concept, current skill, review.
// Never silently relabel a different skill as mastery in the chosen focus.
function routeChoice({zoneId,focusId,step=0,progress={},reviewQueue=[],finished=0}){
 const focus=skillById[focusId];if(!focus?.playable)return null;
 const inZone=playableSkills.filter(s=>s.zone===zoneId);
 const prereqs=(focus.prerequisites||[]).map(id=>skillById[id]).filter(s=>s?.playable);
 const siblings=inZone.filter(s=>s.id!==focusId&&!s.prerequisites.includes(focusId));
 const due=reviewQueue.find(e=>e.dueAt<=finished&&inZone.some(s=>s.id===e.skillId));
 const seen=siblings.filter(s=>progress[s.id]?.attempts>0);
 const sibling=seen.length?seen.sort((a,b)=>(progress[a.id]?.lastSeen||0)-(progress[b.id]?.lastSeen||0))[0]:siblings[step%siblings.length];
 const warmup=prereqs.length?prereqs[0]:sibling;
 const position=step%5;
 if(position===4&&due)return {skillId:due.skillId,role:'Recall'};
 if(position===0&&warmup)return {skillId:warmup.id,role:'Warm-up'};
 if(position===2&&(sibling||warmup))return {skillId:(sibling||warmup).id,role:'Explore a connection'};
 return {skillId:focusId,role:position===4?'Try another way':'Main challenge'};
}

