function emptyExhibit(){return {pieces:[],catalogue:[],equipment:[],completed:false};}
function sanitiseMuseum(museum={}){
 const out={};
 for(const species of museumSpecies){
  const obj=museum?.[species.key]||{};
  const pieces=Array.isArray(obj.pieces)?[...new Set(obj.pieces.filter(id=>museumParts.some(p=>p.id===id)))]:[];
  out[species.key]={pieces,catalogue:Array.isArray(obj.catalogue)?obj.catalogue.filter(id=>/^f\d+$/.test(id)).slice(0,4):[],equipment:Array.isArray(obj.equipment)?obj.equipment.filter(id=>/^e\d+$/.test(id)).slice(0,2):[],completed:pieces.length===museumParts.length};
 }
 return out;
}
function availableSpecimen(collectionCounts,museum,type){
 const used={};
 for(const exhibit of Object.values(museum||{})){
  for(const id of type==='Fossil'?(exhibit.catalogue||[]):(exhibit.equipment||[]))used[id]=(used[id]||0)+1;
 }
 const prefix=type==='Fossil'?'f':'e';
 return Object.entries(collectionCounts||{}).filter(([id,n])=>new RegExp(`^${prefix}\\d+$`).test(id)&&Number(n)>(used[id]||0))
  .map(([id,n])=>({id,available:Math.max(0,Math.floor(Number(n))-(used[id]||0))})).sort((a,b)=>Number(a.id.slice(1))-Number(b.id.slice(1)));
}
function canPlace(exhibit,part){return museumParts.some(p=>p.id===part)&&!(exhibit.pieces||[]).includes(part);}
// Schematic, consistent species-specific bone outlines. Always use the same species portrait beside the display.
