// app.js






const KEY='dinomath.sanctuary.v4';
const defaults=()=>({name:'Explorer',quiet:false,museum:{},progress:{},collection:[],collectionCounts:{},researchFinds:0,pendingRewards:[],finished:0,solved:0,fossils:0,goal:3,preferredSkill:'number.signed',manualTier:'auto',selectedTiers:{},lastZone:'ridge',revealSteps:0,reviewQueue:[],exploredRegions:[],missionPreference:'trail',feelings:[],visits:0});
function load(){
 try {
  let s=JSON.parse(localStorage.getItem(KEY));
  if(!s){s=JSON.parse(localStorage.getItem('dinomath.sanctuary.v3'));if(s){s.migratedFromV3=true;} }
  if(!s){s=JSON.parse(localStorage.getItem('dinomath.sanctuary.v2'));if(s){
    // Keep maths progress; convert old species IDs by species identity, never by position.
    const dMap={'d1':'d10','d2':'d0','d3':'d11','d4':'d6','d6':'d7','d10':'d2'};
    s.collection=[...new Set((s.collection||[]).flatMap(id=>id.startsWith('d')?(dMap[id]?[dMap[id]]:[]):[id]))];
    s.revealSteps=0;s.reviewQueue=[];s.migratedFromV2=true;
  }}
  if(s&&typeof s==='object'){
    const unique=Array.isArray(s.collection)?[...new Set(s.collection)]:[];
    const counts={...(s.collectionCounts||{})};
    // Preserve every fossil/equipment item collected in previous versions.
    for(const id of unique)if(!counts[id])counts[id]=1;
    return {...defaults(),...s,museum:sanitiseMuseum(s.museum),progress:s.progress||{},collection:unique,collectionCounts:counts,
       researchFinds:Number.isInteger(s.researchFinds)&&s.researchFinds>=0?s.researchFinds:0,
       pendingRewards:Array.isArray(s.pendingRewards)?s.pendingRewards:[],
       selectedTiers:s.selectedTiers||{},reviewQueue:Array.isArray(s.reviewQueue)?s.reviewQueue:[],
       exploredRegions:Array.isArray(s.exploredRegions)?s.exploredRegions:[],feelings:Array.isArray(s.feelings)?s.feelings:[],
       visits:Number.isInteger(s.visits)?s.visits:0};
   }
 }catch(err){console.warn('Could not load local progress',err);}
 return defaults();
}
