let museumDino='baryonyx',museumSelected='',museumMessage='',museumMistakes=0,museumModel=2,museumFactor=3;
const app=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>String(x).replaceAll('-','−');
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch(err){console.warn('Could not save',err);}};
const progress=id=>({...EMPTY_SKILL(),...(state.progress[id]||{})});
const area=id=>zones.find(z=>z.id===id)||zones[0];
const inBag=id=>state.collection.includes(id);
const isStackable=item=>item?.type==='Fossil'||item?.type==='Equipment';
const itemCount=item=>Math.max(0,Number(state.collectionCounts?.[item.id])||0);
const totalEarned=()=>state.collection.length+state.collection.reduce((n,id)=>{
 const item=rewards.find(x=>x.id===id);
 return n+(isStackable(item)?Math.max(0,itemCount(item)-1):0);
},0);
function syncRewardQueue(){rewardPopup=state.pendingRewards[0]||null;popupQueue=state.pendingRewards.slice(1);}
function queueReward(item,reason,kind='find'){
 if(!item||(!isStackable(item)&&inBag(item.id)))return;
 if(!inBag(item.id))state.collection.push(item.id);
 let quantity=1;
 if(isStackable(item)){
   quantity=itemCount(item)+1;
   state.collectionCounts[item.id]=quantity;
 }
 const event={...item,reason,kind,quantity,repeat:isStackable(item)&&quantity>1};
 state.pendingRewards.push(event);
 syncRewardQueue();save();
}
function currentDino(){return nextDinosaur(state.collection);}
function addDiscovery(){
 const d=currentDino();
 if(d){
  state.revealSteps=Math.min(8,(Number(state.revealSteps)||0)+1);
  if(state.revealSteps===4){
    const egg=rewards.find(x=>x.id===`egg${d.id.slice(1)}`);
    queueReward(egg,'A mystery egg discovered!','egg');
  }
  if(state.revealSteps>=8){
    queueReward(d,'A new dinosaur hatched!','hatch');
    state.revealSteps=0;
  }
 }
 // Fossils and lab equipment emerge steadily; these do not depend on perfect answers.
 if(state.finished===1||state.finished%3===0){const item=researchRewardAt(state.researchFinds++);queueReward(item,'A field discovery!','find');}
}
function revealMosaic(species,steps,compact=false){
 if(!species)return `<p class="muted">All dinosaurs discovered! What an expedition.</p>`;
 const tiles=Array.from({length:8},(_,i)=>`<div class="portrait-tile ${i<steps?'revealed':''}" style="--xp:${(i%4)*100/3}%;--yp:${Math.floor(i/4)*100}%" aria-hidden="true"></div>`).join('');
 return `<div class="portrait ${compact?'portrait-compact':''}" style="--portrait:url('${species.image}')" role="img" aria-label="${steps} of 8 pieces of a mystery dinosaur portrait revealed">${tiles}</div>`;
}
function portraitPanel(compact=false){const d=currentDino();if(!d)return '';
 return `<div class="portrait-panel ${compact?'compact':''}"><div><div class="eyebrow">🧩 Mystery dinosaur</div><strong>${state.revealSteps}/8 picture pieces</strong><p class="tiny muted">Every completed puzzle reveals another piece. At four, find an egg. At eight, it hatches!</p></div>${revealMosaic(d,state.revealSteps,true)}</div>`;
}
function header(){return `<header class="header"><button class="logo" data-action="home" aria-label="Home"><img src="./assets/dr-bones/portrait.webp" alt=""><span>Dino<em>Math</em></span></button><div class="top-actions"><button class="quiet-toggle" data-action="quiet" aria-pressed="${state.quiet}">${state.quiet?'◉ Quiet on':'◌ Quiet mode'}</button><button class="chip" data-action="parent">⚙ Parent</button></div></header>`;}
function render(){document.body.classList.toggle('quiet',!!state.quiet);app.innerHTML=`<div class="shell">${header()}<main id="main-content">${screen==='home'?home():screen==='zone'?zonePage():screen==='mission'?mission():screen==='end'?endPage():screen==='journal'?journal():screen==='dig'?digPage():screen==='workshop'?workshopPage():screen==='museum'?museumPage():parent()}</main><footer class="footer">DinoMath 0.5 · A calm, local-first prototype · No ads, accounts or tracking</footer></div>${rewardPopup&&showRewardModal?rewardOverlay():''}`;}
function home(){const suggested=skillById[state.preferredSkill]?.playable?skillById[state.preferredSkill]:suggestSkill(state.progress);
 return `<section class="hero" aria-label="Dinosaur sanctuary"><div class="hero-content"><div class="eyebrow">Your prehistoric research station</div><h1 class="h1">Explore. Solve.<br>Discover.</h1><p>Build a dinosaur collection, solve mysteries and explore at your own pace. One question is enough for a visit.</p><div class="hero-actions"><button class="main-btn" data-action="route" data-zone="${esc(suggested.zone)}" data-skill="${esc(suggested.id)}">Continue Discovery Trail →</button><button class="alt-btn" data-action="dig">Dig for fossils 🦴</button><button class="alt-btn" data-action="museum">Build a skeleton 🦴</button></div><p class="tiny" style="margin-top:14px"><button class="text-button" data-action="journal">🎒 View my collection · ${totalEarned()} finds</button></p></div><img class="hero-bones" src="./assets/dr-bones/welcome.webp" alt="Dr Bones, your friendly palaeontologist guide"></section>
 <div class="hero-banner"><img src="./assets/dr-bones/portrait.webp" alt=""><div><strong>Dr Bones:</strong>“Hello, ${esc(state.name)}! Questions are things we investigate, one step at a time.”</div></div>
 ${portraitPanel()}<div class="summary-ribbon"><button data-action="museum" class="summary-pill">🏛️ <strong>${Object.values(sanitiseMuseum(state.museum)).filter(x=>x.completed).length}</strong> museum exhibits</button><button data-action="journal" class="summary-pill">🎒 <strong>${totalEarned()}</strong> items collected</button><span class="summary-pill">🧩 <strong>${state.finished}</strong> puzzles completed</span><span class="summary-pill">🦴 <strong>${state.fossils}</strong> fossils brushed</span>${rewardPopup?`<button class="summary-pill new-rewards" data-action="see-reward">🎁 View ${1+popupQueue.length} discoveries</button>`:''}</div>
 <div class="section-heading"><div><h2>Where shall we explore?</h2><p>Eight destinations, each with a hands-on maths workshop and a guided discovery trail. You can still practise one skill at a time.</p></div></div>
 <div class="zone-grid">${zones.map(z=>`<button class="zone-card" data-action="zone" data-zone="${z.id}" style="--cardcolor:${z.color}"><span class="zone-emoji" aria-hidden="true">${z.icon}</span><img class="zone-art" src="${dinosaurs.find(d=>d.title===z.species)?.image||''}" alt="" loading="lazy"><span class="zone-name">${esc(z.name)}</span><span class="zone-sub">${esc(z.subtitle)}</span><span class="zone-count">${playableSkills.filter(s=>s.zone===z.id).length} skills · ${state.exploredRegions.includes(z.id)?'✓ visited':'new place'}</span></button>`).join('')}</div><div class="bottom-hint">No timers, no broken streaks, no compulsory daily sessions. You can stop whenever you want.</div>`;
}
function statusFor(id){const p=progress(id),chosen=state.selectedTiers[id]||p.tier||1,s=tierStats(p,chosen);return {p,chosen,s};}
function zonePage(){const z=area(zone),items=playableSkills.filter(s=>s.zone===zone);
 return `<div class="page-top"><button class="back" data-action="home">← Sanctuary</button><div class="zone-intro" style="--zone-bg:${z.color}"><div class="big-emoji" aria-hidden="true">${z.icon}</div><div><div class="eyebrow">${esc(z.subtitle)}</div><h1 class="h2">${esc(z.name)}</h1><p>${esc(z.description)} Each skill has four challenges that unlock with practice.</p></div></div></div><div class="zone-actions-panel"><div><div class="eyebrow">Today's investigation</div><strong>${esc(z.goal)}</strong><p>Take a short mixed trail through related maths ideas, or explore a model with Dr Bones first.</p></div><div class="zone-action-buttons"><button class="main-btn" data-action="route" data-zone="${z.id}">🧭 Discovery Trail</button><button class="alt-btn" data-action="workshop" data-zone="${z.id}">🧪 Dr Bones’ workshop</button></div></div><div class="section-heading"><div><h2>Or focus on one skill</h2><p>Ten puzzles per challenge, spread across visits. This is where you can practise a particular idea.</p></div></div>
 <div class="skill-grid">${items.map(s=>{const {p,chosen,s:st}=statusFor(s.id);const level= Math.min(4,state.selectedTiers[s.id]||p.tier||1);const stat=tierStats(p,level);return `<div class="skill-tile"><h3>${esc(s.title)}</h3><p class="tiny muted">${p.attempts?`${p.attempts} puzzles explored`:'New expedition'}</p><div class="level-row">${[1,2,3,4].map(n=>`<button class="level-dot ${n===level?'active':''} ${n>p.unlockedTier?'locked':''}" data-action="choose-tier" data-skill="${s.id}" data-tier="${n}" ${n>p.unlockedTier?'disabled':''} title="Challenge ${n}${n>p.unlockedTier?' locked':''}" aria-label="Challenge ${n}${n>p.unlockedTier?' locked':''}" aria-pressed="${n===level}">${n>p.unlockedTier?'🔒':n}</button>`).join('')}</div><div class="tier-track"><div style="width:${Math.min(100,stat.attempts*10)}%"></div></div><p class="tiny muted">Challenge ${level} · ${Math.min(10,stat.attempts)}/10 practice · more adventures ahead</p><button class="main-btn skill-start" data-action="start" data-skill="${s.id}">Explore this skill →</button></div>`}).join('')}</div><p class="bottom-hint">A grown-up can jump to any challenge from the parent dashboard. Skills in other regions remain accessible.</p>`;
}
function chooseTier(){const p=progress(skillId);const preferred=Number(state.selectedTiers[skillId]);if(missionStyle==='trail'&&skillId!==missionFocus)return Math.max(1,Math.min(4,preferred||p.tier||1));return state.manualTier!=='auto'?Number(state.manualTier):Math.max(1,Math.min(4,preferred||p.tier||1));}
function nextQuestion(){if(missionStyle==='trail'){const plan=routeChoice({zoneId:expeditionZone,focusId:missionFocus,step:sessionDone,progress:state.progress,reviewQueue:state.reviewQueue,finished:state.finished});if(plan){skillId=plan.skillId;questionRole=plan.role;}}else questionRole='Skill focus';
 const tier=chooseTier();let desiredTier=tier;isRevisit=false;let sourceStem='';
 const dueIndex=state.reviewQueue.findIndex(e=>e.skillId===skillId&&state.finished>=e.dueAt);
 if(dueIndex>=0){const entry=state.reviewQueue.splice(dueIndex,1)[0];desiredTier=entry.tier;sourceStem=entry.sourceStem;isRevisit=true;save();}
 let draft;for(let n=0;n<25;n++){draft=generateQuestion(skillId,desiredTier);if(!recentStems.includes(draft.stem)&&draft.stem!==sourceStem)break;}
 q=draft;recentStems=[...recentStems,q.stem].slice(-9);
 selected=['slider','stepper'].includes(q.mode)?String(q.visual.start):q.mode==='fractionbuild'?'0/2':'';
 hint=false;hadMiss=false;feedback='';levelUp=false;interacted=false;}
function startMission(id,style='focus',where=null){if(!skillById[id]?.playable)return;missionStyle=style;missionFocus=id;skillId=id;expeditionZone=where||skillById[id].zone;zone=expeditionZone;state.preferredSkill=id;state.lastZone=zone;save();sessionDone=0;sessionRight=0;recentMisses=0;state.visits=(state.visits||0)+1;visitSerial=state.visits;save();recentStems=[];nextQuestion();screen='mission';render();scrollTop();}
function startTrail(where,requestedSkill){const items=playableSkills.filter(s=>s.zone===where);if(!items.length)return;const preferred=skillById[requestedSkill||state.preferredSkill];const focus=preferred?.playable&&preferred.zone===where?preferred:items.slice().sort((a,b)=>(state.progress[b.id]?.attempts||0)-(state.progress[a.id]?.attempts||0))[0];startMission(focus.id,'trail',where);}
function openWorkshop(where,back=screen){workshopBack=back;workshopZone=zones.some(z=>z.id===where)?where:'ridge';labModel=initialModel(workshopZone);screen='workshop';render();scrollTop();}
function workshopPage(){const z=area(workshopZone),w=workshops[workshopZone];return `<div class="page-top"><button class="back" data-action="lab-back">← ${workshopBack==='mission'?'Back to question':'Back to '+esc(z.name)}</button><div class="eyebrow">🧪 Dr Bones’ maths workshop</div><h1 class="h2">${esc(w.title)}</h1><p class="muted">${esc(w.idea)}</p></div><section class="panel workshop-panel"><div class="bones-box"><img src="./assets/dr-bones/${['ridge','station'].includes(workshopZone)?'pointing':'explaining'}.webp" alt=""><div><strong>Try something</strong><p>${esc(w.prompt)} There are no wrong answers here, and nothing is being scored.</p></div></div><div class="model-stage" aria-live="polite">${modelMarkup(workshopZone,labModel.a,labModel.b)}</div><details class="math-help"><summary>What am I looking for?</summary><ol>${w.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details><div class="action-row"><button class="main-btn" data-action="lab-back">${workshopBack==='mission'?'Back to my question →':'Back to the adventure →'}</button><button class="alt-btn" data-action="route" data-zone="${z.id}">Try a Discovery Trail</button></div></section>`;}

function visual(v){if(!v||!v.kind)return '';
 if(v.kind==='eggs')return `<div class="visual"><div class="eggs" aria-label="Eggs to count">${Array.from({length:Math.min(v.count,20)},()=>'<span class="egg" aria-hidden="true">🥚</span>').join('')}</div></div>`;
 if(v.kind==='groups')return `<div class="visual"><div class="groups">${Array.from({length:v.b},()=>`<div class="group">${Array.from({length:v.a},()=>'<span aria-hidden="true">🌿</span>').join('')}</div>`).join('')}</div>${v.abstract?'<p class="visual-note">A smaller model of equal groups is shown.</p>':''}</div>`;
 if(v.kind==='fraction')return `<div class="visual"><div class="fraction-bars">${v.parts.map(p=>`<div class="fraction-bar"><div class="fraction-label">${esc(p.label||`${p.n}/${p.d}`)}</div><div class="frac-cells">${Array.from({length:Math.min(p.d,20)},(_,i)=>`<div class="frac-cell ${i<p.n?'filled':''}"></div>`).join('')}</div></div>`).join('')}</div></div>`;
 if(v.kind==='rect')return `<div class="visual"><div class="rect-model" aria-label="Rectangle with labelled dimensions"><span>${v.width} m</span><div>${v.height} m</div></div></div>`;
 if(v.kind==='numberline'){
   const limit=Math.max(5,Math.abs(v.start),Math.abs(v.end))+2,min=-Math.min(65,limit),max=Math.min(65,limit);
   if(q.mode==='slider'||q.mode==='stepper')return `<div class="visual"><div class="lift-label">🚡 Research lift position: <strong id="lift-value">${fmt(selected)}</strong> m</div><input class="numberline-slider" data-slider type="range" min="${min}" max="${max}" step="1" value="${esc(selected)}" aria-label="Select final position" ${q.mode==='stepper'?'disabled':''}><div class="ticks"><span>${fmt(min)}</span><span>0</span><span>+${max}</span></div></div>`;
   return `<div class="visual"><div class="equation">📍 Start ${fmt(v.start)} m · move ${v.move<0?'down':'up'} ${Math.abs(v.move)} m</div></div>`;
 }
 return `<div class="visual"><div class="equation">${esc(v.display||v.number||'🧩')}</div></div>`;
}
function answerUI(){
 if(q.mode==='slider')return `<div class="answer-label">Move the lift to its destination</div>`;
 if(q.mode==='stepper')return `<div class="stepper-panel"><span class="answer-label">Move the lift, one step at a time</span><div class="stepper-row"><button class="alt-btn" data-action="step" data-delta="-1" aria-label="Move one step down">− 1</button><strong id="step-position">${fmt(selected)}</strong><button class="alt-btn" data-action="step" data-delta="1" aria-label="Move one step up">+ 1</button></div></div>`;
 if(q.mode==='fractionbuild'){
   const [n,d]=selected.split('/').map(Number);
   const denominators=[2,3,4,5,6,8,10,12];
   return `<div class="fraction-builder"><div class="answer-label">Build your answer as a fraction</div><p class="small muted">Choose the number of equal parts, then tap to shade the amount.</p><div class="denom-options">${denominators.map(x=>`<button class="denom-choice ${d===x?'active':''}" data-action="denom" data-value="${x}" aria-pressed="${x===d}">${x}</button>`).join('')}</div><div class="build-cells">${Array.from({length:d},(_,i)=>`<button class="build-cell ${i<n?'filled':''}" data-action="fill" data-value="${i+1}" aria-label="Shade ${i+1} of ${d} parts" aria-pressed="${i<n}"></button>`).join('')}</div><div class="built-fraction" aria-live="polite">${n}/${d}</div></div>`;
 }
 if(q.mode==='order'){const chosen=selected?selected.split('|'):[];return `<div class="answer-entry"><div class="answer-label">Build the sequence</div><div class="ordering-selected">${chosen.length?chosen.map(v=>`<span class="ordered-slot">${esc(v)}</span>`).join(''):'<span class="muted">Tap a number to add it</span>'}</div><div class="order-tiles">${q.tokens.map(t=>`<button class="choice" data-action="order-pick" data-value="${esc(t)}" ${chosen.includes(t)?'disabled':''}>${esc(t)}</button>`).join('')}</div><button class="text-button" data-action="order-clear">Clear order</button></div>`;}
 if(q.mode==='type'||q.mode==='repair')return `<div class="answer-entry"><label class="answer-label" for="math-input">${q.mode==='repair'?'Check Dr Bones’ calculation':'Your answer'}</label><input id="math-input" data-math-input type="text" inputmode="decimal" autocapitalize="off" autocomplete="off" spellcheck="false" placeholder="e.g. −3 or 3/4" value="${esc(selected)}"><p class="helper-note">Fractions can be typed as 3/4. Equivalent fractions count.</p></div>`;
 return `<div class="answer-label">Choose an answer — one attempt per puzzle</div><div class="choices">${q.choices.map(o=>`<button class="choice ${String(selected)===o.value?'selected':''}" data-action="select" data-value="${esc(o.value)}" aria-pressed="${String(selected)===o.value}">${esc(String(o.label).replace(/-/g,'−'))}</button>`).join('')}</div>`;
}
function mission(){if(!q)return home();const s=skillById[skillId],z=area(s.zone),p=progress(skillId),st=tierStats(p,q.tier),complete=['complete','shown','wrong'].includes(feedback);
 return `<div class="mission-shell"><div class="mission-head"><button class="back" data-action="zone" data-zone="${expeditionZone||z.id}">← ${esc(area(expeditionZone||z.id).name)}</button><span class="crumb">${state.goal?`${Math.min(state.goal,sessionDone+(complete?0:1))} / ${state.goal} this visit`:'Explore freely'}</span><button class="text-button tiny" data-action="end">Finish now</button></div>
 <div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,st.attempts*10)}%"></div></div><p class="tiny muted level-caption">${missionStyle==='trail'?`🧭 ${esc(questionRole)} · `:''}${esc(s.title)} · Challenge ${q.tier} of 4 · ${Math.min(10,st.attempts)}/10 practice completed</p>
 ${isRevisit?`<p class="review-note">🔎 A fresh version of a question we investigated earlier — no rush.</p>`:''}<details class="portrait-details"><summary>🧩 Mystery portrait · ${state.revealSteps}/8 pieces</summary>${portraitPanel(true)}</details><div class="mission-panel"><div class="mission-art"><span class="mission-icon">${z.icon}</span><span class="mission-art-text">${esc(s.title)}<br><span class="muted">${esc(({slider:'Move the number line',stepper:'Move step by step',fractionbuild:'Build a fraction',repair:'Repair the calculation',type:'Work it out',choice:'Choose an answer',order:'Arrange the numbers'})[q.mode]||'Investigate')}</span></span></div><div class="question-content"><div class="eyebrow">${missionStyle==='trail'?`Discovery Trail · ${esc(area(expeditionZone).name)}`:'Your next discovery'}</div><h1 class="question-stem">${esc(q.stem)}</h1>${visual(q.visual)}${!complete?answerUI():''}
 
 ${complete?`<div class="feedback" role="status"><h3>${feedback==='wrong'?'Something to investigate 🔎':feedback==='shown'?'Mystery explained 🔎':'Method uncovered 🌿'}</h3><p>${feedback==='wrong'?'That result doesn’t quite fit. Here’s a method to explore; a different example will appear later. ':''}${esc(q.explanation)}</p>${feedback==='wrong'?`<div class="coach-followup"><img class="bones-coach-avatar" src="./assets/dr-bones/puzzled.webp" alt="" aria-hidden="true"><strong>Dr Bones:</strong> ${esc(supportFor(s,s.zone).watch)}<p>${esc(supportFor(s,s.zone).misconception)}</p><button class="alt-btn" data-action="workshop" data-zone="${s.zone}">Show me with a model 🧪</button>${recentMisses>=2?'<p class="tiny muted">Two tricky questions in a row? It is fine to take a break or try a gentler topic.</p>':''}</div>`:''}<p class="mini-reward">🧩 Another piece of the mystery picture uncovered</p>${rewardPopup?`<div class="calm-reward"><button class="alt-btn" data-action="see-reward">🎁 Open my new discoveries (${1+popupQueue.length})</button><p class="tiny muted">Or continue your maths; they are already safe in your collection.</p></div>`:''}${levelUp?`<p class="unlock-message">🎉 Challenge ${Math.min(4,q.tier+1)} unlocked for this skill!</p>`:''}<div class="feedback-actions"><button class="main-btn" data-action="next">${state.goal&&sessionDone>=state.goal?'Finish expedition →':'Another discovery →'}</button><button class="alt-btn" data-action="end">Finish now</button></div></div>`:
 `<div class="action-row"><button class="main-btn" data-action="check" ${(selected===''||(q.mode==='order'&&selected.split('|').length!==q.tokens.length)||(['fractionbuild','stepper','slider'].includes(q.mode)&&!interacted))?'disabled':''}>Check my idea</button><button class="alt-btn" data-action="hint">${hint?'Hide help':'Ask Dr Bones for a hint'}</button><button class="text-button" data-action="skip">Try a different puzzle</button></div><div class="gentle-actions"><button class="text-button" data-action="show">Show me how to solve it</button>${q.tier>1?'<button class="text-button" data-action="gentle">Try a smaller step</button>':''}</div>
 ${hint?`<div class="bones-box"><img src="./assets/dr-bones/thinking.webp" alt=""><div><strong>Dr Bones' field note</strong><p>${esc(q.hint)}</p><p class="small muted">${esc(supportFor(s,s.zone).watch)}</p><button class="text-button" data-action="workshop" data-zone="${s.zone}">Explore a hands-on model →</button></div></div>`:''}
 `}
 <p class="helper-note">One try per question. If it doesn’t work, Dr Bones shows another approach, and a different example returns later. You can stop whenever you like.</p></div></div></div>`;
}
function complete(correct,wasShown=false,wasWrong=false){
 if(['complete','shown','wrong'].includes(feedback))return;
 const earlier=progress(skillId);
 const current=recordAttempt(earlier,{correct,hintUsed:hint||wasShown||wasWrong,tier:q.tier,mode:q.mode});state.progress[skillId]=current;
 levelUp=current.newUnlock;sessionDone++;state.finished++;
 if(correct){sessionRight++;state.solved++;recentMisses=0;}else recentMisses++;
 if(levelUp)state.selectedTiers[skillId]=current.unlockedTier;
 feedback=wasWrong?'wrong':wasShown?'shown':'complete';
 if(!correct){
  const pending=state.reviewQueue.filter(x=>x.skillId===skillId);
  if(pending.length<3)state.reviewQueue.push({skillId,tier:q.tier,dueAt:state.finished+2,sourceStem:q.stem});
 }
 if(!state.exploredRegions.includes(expeditionZone)){state.exploredRegions.push(expeditionZone);queueReward(locationRewards.find(x=>x.zone===expeditionZone),'New location explored!','find');}
 addDiscovery();save();render();
}
function evaluate(){
 if(!q||['complete','shown','wrong'].includes(feedback)||selected===''||(['fractionbuild','stepper','slider'].includes(q.mode)&&!interacted))return;
 if(isCorrect(q,selected))complete(true);
 else complete(false,false,true); // One *submitted* attempt, not unlimited elimination of options.
}
function showAnswer(){if(['complete','shown','wrong'].includes(feedback))return;hint=true;complete(false,true,false);}
function skipQuestion(){sessionDone++;if(state.goal&&sessionDone>=state.goal){screen='end';}else nextQuestion();render();scrollTop();}
function endPage(){const s=skillById[skillId],st=tierStats(progress(skillId),Math.min(4,progress(skillId).tier));return `<div class="mission-end panel"><div class="end-icon" aria-hidden="true">🦕</div><div class="eyebrow">Expedition saved</div><h1 class="h2">Nice exploring, ${esc(state.name)}!</h1><p>You explored ${sessionDone} question${sessionDone===1?'':'s'} this visit. Your discoveries are safe here for next time.</p><div class="end-stats"><span>🎒 ${totalEarned()} finds</span><span>🧩 ${state.finished} puzzles explored</span></div><div class="feeling-panel"><strong>How did this adventure feel?</strong><p class="tiny muted">This helps us choose a comfortable next adventure. There is no right answer.</p><div class="feeling-buttons">${[['easy','🙂 Comfortable'],['okay','😐 About right'],['hard','😣 Too tricky']].map(([id,label])=>`<button class="alt-btn" data-action="feeling" data-value="${id}" ${state.feelings.at(-1)?.visit===visitSerial&&state.feelings.at(-1)?.value===id?'aria-pressed="true"':''}>${label}</button>`).join('')}</div>${state.feelings.at(-1)?.visit===visitSerial?`<p class="tiny muted">Thanks for telling us. You can choose a workshop or a gentler challenge next time.</p>`:''}</div>${rewardPopup?`<div class="calm-reward"><button class="alt-btn" data-action="see-reward">🎁 See ${1+popupQueue.length} saved discoveries</button></div>`:''}<div class="action-row" style="justify-content:center"><button class="main-btn" data-action="zone" data-zone="${expeditionZone||s?.zone||zone}">Explore the region</button><button class="alt-btn" data-action="journal">See my collection</button><button class="text-button" data-action="home">Sanctuary home</button></div><div class="bones-box"><img src="./assets/dr-bones/portrait.webp" alt=""><div><strong>Dr Bones</strong><p>“Our notes are saved. We can explore again whenever you’re ready.”</p></div></div></div>`;}
function journal(){
 const owned=rewards.filter(x=>inBag(x.id));const types=['All','Dinosaur','Egg','Fossil','Equipment','Location'];
 const filtered=journalFilter==='All'?rewards:rewards.filter(x=>x.type===journalFilter);
 const view=[...filtered.filter(x=>inBag(x.id)),...filtered.filter(x=>!inBag(x.id))].slice(0,journalVisible);
 return `<div class="page-top"><button class="back" data-action="home">← Sanctuary</button><div class="eyebrow">Field journal</div><h1 class="h2">My discoveries 🎒</h1><p class="muted">${owned.length} of ${rewards.length} different discoveries · ${totalEarned()} items including extra fossils and equipment · ${dinosaurs.filter(d=>inBag(d.id)).length} dinosaur species.</p><div class="collection-progress"><div style="width:${100*owned.length/rewards.length}%"></div></div></div><div class="filter-row">${types.map(x=>`<button class="filter-pill ${journalFilter===x?'active':''}" data-action="filter" data-filter="${x}">${x}</button>`).join('')}</div>
 <div class="museum-teaser"><div><strong>🏛️ Fossil Reconstruction Workshop</strong><p>Use your discoveries to prepare a dinosaur museum. Extra fossils and tools make your exhibits richer.</p></div><button class="main-btn" data-action="museum">Build a skeleton →</button></div><div class="collection-grid">${view.map(item=>{
 const yes=inBag(item.id);
 return `<div class="collection-card ${yes?'':'hidden-find'}">${yes&&item.type==='Dinosaur'?`<img class="species-art" src="${item.image}" alt="Illustration of ${esc(item.title)}">`:`<div class="collect-icon" aria-hidden="true">${yes?(item.icon||'🥚'):'?'}</div>`}<span class="collect-type">${item.type}</span>${yes&&isStackable(item)?`<span class="item-count" aria-label="${itemCount(item)} copies">×${itemCount(item)}</span>`:''}<h3>${yes?esc(item.title):'Undiscovered'}</h3><p>${yes?esc(item.fact):'Explore to reveal this find.'}</p>${yes&&item.region?`<p class="region-tag">📍 ${esc(item.region)} · ${esc(item.period)}</p>`:''}</div>`;
 }).join('')}</div>${journalVisible<filtered.length?`<div class="journal-more"><button class="alt-btn" data-action="journal-more">Show more discoveries</button></div>`:''}</div>`;
}
function digPage(){const spots=[1,4,7,10];return `<div class="page-top"><button class="back" data-action="home">← Sanctuary</button><div class="eyebrow">Free exploration</div><h1 class="h2">The fossil dig 🦴</h1><p class="muted">Brush away the sand and see what you find. No maths questions required.</p></div><div class="panel dig-panel"><div class="dig-field">${Array.from({length:12},(_,i)=>`<button class="dig-tile ${digTiles.has(i)?'uncovered':''}" data-action="brush" data-index="${i}" ${digTiles.has(i)?'disabled':''} aria-label="${digTiles.has(i)?'Uncovered': 'Brush'} square ${i+1}">${digTiles.has(i)?spots.includes(i)?'🦴':'🪨':'✦'}</button>`).join('')}</div><div class="bones-box"><img src="./assets/dr-bones/investigating.webp" alt=""><div><strong>Dr Bones</strong><p>“Each find tells us something about the past. Shall we investigate another patch?”</p></div></div><div class="action-row"><button class="alt-btn" data-action="dig-reset">Explore a new dig</button><button class="main-btn" data-action="museum">Build a skeleton</button><button class="alt-btn" data-action="journal">Visit my collection</button><button class="text-button" data-action="home">Leave the dig</button></div></div>`;}
function museumProgress(){return state.museum?.[museumDino]||emptyExhibit();}
function museumPage(){
 const species=museumSpecies.find(d=>d.key===museumDino)||museumSpecies[0];
 const info=dinosaurs.find(d=>d.id===species.id);
 const m=museumProgress(),placed=m.pieces||[],completed=placed.length===museumParts.length;
 const specimens=availableSpecimen(state.collectionCounts,state.museum,'Fossil').filter(x=>m.catalogue.length<4);
 const tools=availableSpecimen(state.collectionCounts,state.museum,'Equipment').filter(x=>m.equipment.length<2);
 const attachedFossils=(m.catalogue||[]).map(id=>rewards.find(r=>r.id===id)).filter(Boolean);
 const attachedTools=(m.equipment||[]).map(id=>rewards.find(r=>r.id===id)).filter(Boolean);
 const statuses=Object.values(sanitiseMuseum(state.museum));
 return `<div class="page-top museum-heading"><button class="back" data-action="home">← Sanctuary</button><div class="eyebrow">🏛️ The Fossil Reconstruction Workshop</div><h1 class="h2">Build your dinosaur museum</h1><p class="muted">Fit seven sets of bones onto a fossil mount. Tap a bone card, then tap where it belongs. Take your time; there are no scores or timers.</p></div>
 <div class="museum-stats"><span>🦴 ${statuses.filter(s=>s.completed).length}/${museumSpecies.length} skeletons assembled</span><span>🔬 ${Object.values(state.museum||{}).reduce((n,s)=>n+(s.catalogue?.length||0)+(s.equipment?.length||0),0)} finds catalogued</span><span>🎒 ${totalEarned()} collection items</span></div>
 <div class="museum-chooser" role="group" aria-label="Choose a dinosaur skeleton">${museumSpecies.map(d=>`<button class="museum-species ${d.key===museumDino?'chosen':''}" data-action="museum-species" data-species="${d.key}" aria-pressed="${d.key===museumDino}"><img src="${dinosaurs.find(x=>x.id===d.id)?.image||''}" alt=""><span>${esc(d.title)}</span><small>${state.museum?.[d.key]?.completed?'✓ Assembled':`${state.museum?.[d.key]?.pieces?.length||0}/7 bones`}</small></button>`).join('')}</div>
 <section class="panel museum-panel"><div class="museum-topline"><div><div class="eyebrow">${esc(species.site)} · simplified teaching model</div><h2>${esc(species.title)} reconstruction</h2><p class="muted small">${completed?'Your skeleton is assembled! You can improve its research display below.':`${placed.length} of 7 sections placed. Choose a bone and find its position.`}</p></div><img class="museum-reference" src="${info.image}" alt="${esc(info.title)} species-matched illustration"></div>
 <div class="museum-mount">${skeletalDiagram(species,placed)}${museumParts.map((p,i)=>`<button class="mount-target ${placed.includes(p.id)?'fitted':''} ${museumSelected===p.id?'highlight':''}" style="left:${p.x}%;top:${p.y}%" data-action="museum-place" data-part="${p.id}" aria-label="Mount position ${i+1}${placed.includes(p.id)?', fitted with '+p.name:''}" ${placed.includes(p.id)?'disabled':''}>${placed.includes(p.id)?'✓':i+1}</button>`).join('')}</div>
 <p class="museum-status" aria-live="polite">${esc(museumMessage|| (completed?'The skeleton is complete. Your museum can keep growing.':'Dr Bones: “Let’s compare the bone’s shape with the spaces on the mount.”'))}</p>
 ${!completed?`<div class="museum-tray"><div class="eyebrow">Select a bone to place</div><div class="museum-pieces">${museumParts.filter(p=>!placed.includes(p.id)).map(p=>`<button class="museum-piece ${museumSelected===p.id?'selected':''}" data-action="museum-pick" data-part="${p.id}" aria-pressed="${museumSelected===p.id}"><span>${p.id==='skull'?'💀':p.id==='ribs'?'🫁':p.id==='feature'?'⭐':'🦴'}</span>${p.id==='feature'?esc(species.featureName):esc(p.name)}</button>`).join('')}</div><div class="museum-help"><button class="text-button" data-action="museum-hint">Get a clue from Dr Bones</button><details><summary>How to play / position clues</summary><p>Choose one bone card, then tap a numbered circle over the fossil mount. The picture shows a simplified side view with the head on the left and tail on the right. There is no penalty for guessing a position.</p><ul>${museumParts.map((p,i)=>`<li><strong>${i+1}</strong>: ${esc(p.clue)}</li>`).join('')}</ul></details></div></div>`:`<div class="museum-complete" role="status"><strong>🎉 ${esc(species.title)} skeleton assembled!</strong><p>Dr Bones: “We've put the skeleton together. Want to catalogue a fossil or investigate another species?”</p><p class="tiny muted">This is a stylised teaching model, not an anatomically exact reconstruction.</p></div>`}
 </section><section class="panel museum-measure"><div class="eyebrow">📏 Dr Bones’ measuring bench · optional maths workshop</div><h2>Scale up your fossil mount</h2><p class="muted">Imagine a little museum model is ${museumModel} metre${museumModel===1?'':'s'} long. What if the full-size display were ${museumFactor} times as long? Try changing the numbers to see multiplication and scaling in action. <em>These are imaginary measurements for practising maths, not actual dinosaur lengths.</em></p>
 <div class="museum-bench-controls"><div><strong>Model length</strong><div class="museum-control-buttons">${[1,2,3,4].map(n=>`<button class="museum-bench-btn ${n===museumModel?'active':''}" data-action="museum-length" data-value="${n}" aria-pressed="${n===museumModel}">${n} m</button>`).join('')}</div></div><div><strong>Scale factor</strong><div class="museum-control-buttons">${[2,3,4,5].map(n=>`<button class="museum-bench-btn ${n===museumFactor?'active':''}" data-action="museum-factor" data-value="${n}" aria-pressed="${n===museumFactor}">×${n}</button>`).join('')}</div></div></div>
 <div class="museum-length-bars"><div><span>Small model</span><div class="museum-bar" style="width:${museumModel*18}%">${museumModel} m</div></div><div><span>Scaled display</span><div class="museum-bar-row">${Array.from({length:museumFactor},()=>`<div class="museum-unit" style="width:${100/museumFactor}%">${museumModel} m</div>`).join('')}</div></div></div><div class="museum-equation">${museumModel} × ${museumFactor} = <strong>${museumModel*museumFactor} m</strong></div><p class="tiny muted">Try changing the factor. Each equal section represents another copy of the small model.</p></section><section class="panel museum-research"><div class="eyebrow">Specimen preparation laboratory</div><h2>Make this exhibit even better</h2><p class="muted">Your collection stays intact. You can record each copy of a fossil or tool at one museum exhibit. Repeated finds therefore help build more than one display. You can assemble skeletons without collecting anything first.</p>
 <div class="museum-research-grid"><div><h3>🦴 Catalogue fossils <small>${m.catalogue.length}/4</small></h3>${attachedFossils.length?`<div class="museum-tags">${attachedFossils.map(x=>`<span title="${esc(x.fact)}">${esc(x.icon)} ${esc(x.title)}</span>`).join('')}</div>`:'<p class="tiny muted">No research specimens catalogued yet.</p>'}<div class="museum-catalogue">${specimens.length?specimens.map(x=>{const item=rewards.find(r=>r.id===x.id);return item?`<button class="museum-sample" data-action="museum-catalogue" data-item="${x.id}">${esc(item.icon)} ${esc(item.title)} <small>×${x.available}</small></button>`:''}).join(''):'<p class="tiny muted">Collect more fossils in your expeditions or the dig to catalogue them here.</p>'}</div></div>
 <div><h3>🔬 Prepare with equipment <small>${m.equipment.length}/2</small></h3>${attachedTools.length?`<div class="museum-tags">${attachedTools.map(x=>`<span title="${esc(x.fact)}">${esc(x.icon)} ${esc(x.title)}</span>`).join('')}</div>`:'<p class="tiny muted">No tools recorded yet.</p>'}<div class="museum-catalogue">${tools.length?tools.map(x=>{const item=rewards.find(r=>r.id===x.id);return item?`<button class="museum-sample" data-action="museum-equip" data-item="${x.id}">${esc(item.icon)} ${esc(item.title)} <small>×${x.available}</small></button>`:''}).join(''):'<p class="tiny muted">Collect more equipment on your adventures.</p>'}</div></div></div>
 ${completed?`<div class="museum-plaque"><strong>🏛️ ${esc(species.title)} · Field museum exhibit</strong><p>${esc(info.fact)}</p><p>Research record: ${m.catalogue.length} fossil references, ${m.equipment.length} preparation tools.</p></div>`:''}
 <div class="action-row"><button class="alt-btn" data-action="dig">⛏️ Dig for more fossils</button><button class="alt-btn" data-action="journal">🎒 Collection</button><button class="main-btn" data-action="home">Back to sanctuary</button></div></section>`;
}
function catalogueMuseumItem(id,type){
 const species=museumSpecies.find(x=>x.key===museumDino);
 const item=rewards.find(r=>r.id===id&&r.type===type);
 if(!species||!item)return;
 const m=state.museum[museumDino]||emptyExhibit(),field=type==='Fossil'?'catalogue':'equipment',limit=type==='Fossil'?4:2;
 if(m[field].length>=limit||!availableSpecimen(state.collectionCounts,state.museum,type).some(x=>x.id===id&&x.available>0))return;
 m[field].push(id);state.museum[museumDino]=m;museumMessage=`Dr Bones: “I’ve added ${item.title} to the catalogue. ${item.fact}”`;save();render();
}
function rewardOverlay(){
 const item=rewardPopup;const isHatch=item.kind==='hatch',isEgg=item.kind==='egg';
 const art=isHatch?`<div class="hatch-scene" role="img" aria-label="A dinosaur egg cracks and reveals ${esc(item.title)}"><img class="hatch-portrait" src="${item.image}" alt=""><div class="egg-shell egg-left"></div><div class="egg-shell egg-right"></div></div>`:isEgg?`<div class="found-egg" role="img" aria-label="A newly discovered dinosaur egg">🥚</div>`:`<div class="reward-icon" aria-hidden="true">${item.icon||'🦴'}</div>`;
 return `<div class="reward-shade" role="dialog" aria-modal="true" aria-label="New discovery"><div class="reward-box"><div class="eyebrow">✦ ${esc(item.reason)} ✦</div>${art}<div class="collect-type">${esc(item.type)}${item.repeat?' · another copy!':''}</div><h2>${esc(item.title)}${item.quantity>1?' ×'+item.quantity:''}</h2><p>${esc(item.fact)}</p>${isHatch?`<p class="region-tag">📍 ${esc(item.region)} · ${esc(item.period)}</p>`:''}<div class="bones-whisper"><img src="./assets/dr-bones/${isEgg?'egg':'discovery'}.webp" alt="" aria-hidden="true"> Dr Bones: “A new find for the field journal. Shall we take a closer look?”</div><button class="main-btn" data-action="dismiss">${isHatch?'Meet my dinosaur →':'Next discovery ✓'}</button><button class="text-button" data-action="close-rewards">See the rest later (all saved)</button></div></div>`;
}
function parent(){const total=playableSkills.reduce((n,s)=>n+progress(s.id).attempts,0),independent=playableSkills.reduce((n,s)=>n+progress(s.id).independent,0),practised=playableSkills.filter(s=>progress(s.id).attempts>0).length;
 return `<div class="page-top"><button class="back" data-action="home">← Sanctuary</button><div class="eyebrow">Grown-up controls</div><h1 class="h2">Parent dashboard</h1><p class="muted">Choose exact skills, bypass challenge locks, and see what needs practice. These labels stay out of the child's game.</p></div><div class="parent-layout"><section class="panel"><h2>Set the next adventure</h2><div class="control"><label for="parent-name">Explorer's display name</label><input id="parent-name" maxlength="24" value="${esc(state.name)}"></div><div class="control"><label>Quick start</label><div class="preset-row"><button class="preset" data-action="preset" data-preset="young">KS1 foundations</button><button class="preset" data-action="preset" data-preset="middle">KS2 fractions</button><button class="preset" data-action="preset" data-preset="advanced">Signed numbers · early KS3</button></div></div><div class="control"><label for="parent-preference">Next expedition style</label><select id="parent-preference"><option value="trail" ${state.missionPreference==='trail'?'selected':''}>Discovery Trail (mixed and guided)</option><option value="focus" ${state.missionPreference==='focus'?'selected':''}>Skill focus (one skill at a time)</option></select></div><div class="control"><label for="parent-skill">Skill focus</label><select id="parent-skill">${zones.map(z=>`<optgroup label="${esc(z.name)}">${playableSkills.filter(s=>s.zone===z.id).map(s=>`<option value="${s.id}" ${state.preferredSkill===s.id?'selected':''}>${esc(s.title)} (${esc(stages.find(x=>x.id===s.stage)?.band)})</option>`).join('')}</optgroup>`).join('')}</select></div><div class="control"><label for="parent-tier">Challenge override</label><select id="parent-tier"><option value="auto" ${state.manualTier==='auto'?'selected':''}>Adaptive — use unlocked challenge</option>${[1,2,3,4].map(t=>`<option value="${t}" ${String(state.manualTier)===String(t)?'selected':''}>Fixed challenge ${t} (parent override)</option>`).join('')}</select></div><div class="control"><label for="parent-goal">Questions in one visit</label><select id="parent-goal">${[[2,'2 questions'],[3,'3 questions'],[5,'5 questions'],[10,'10 questions'],[0,'No limit; stop whenever']].map(([n,label])=>`<option value="${n}" ${Number(state.goal)===n?'selected':''}>${label}</option>`).join('')}</select></div><div class="parent-teaching"><div class="eyebrow">Teaching support for current focus</div><strong>${esc(skillById[state.preferredSkill]?.title||'Choose a skill')}</strong><p>${esc(supportFor(skillById[state.preferredSkill],skillById[state.preferredSkill]?.zone).watch)}</p><p class="small muted">Useful foundations: ${(skillById[state.preferredSkill]?.prerequisites||[]).map(id=>esc(skillById[id]?.title||id)).join(', ')||'No formal prerequisites'}</p></div><div class="parent-actions"><button class="main-btn" data-action="focus">Start selected expedition →</button><button class="alt-btn" data-action="save-settings">Save settings</button></div><div class="notice"><strong>How challenges unlock:</strong> Each skill has four tiers. Complete at least ten questions on the current tier, with at least seven of the most recent ten correct on the first try without help. Progress carries across visits. Only a first attempt without help counts as independent mastery. Wrong answers are explained once, then a changed example is queued after at least two other completed questions (even across visits). Parent overrides select a starting point without awarding independent mastery.</div></section>
 <section class="panel"><h2>Progress summary</h2><p class="tiny muted">${state.reviewQueue.length} related questions waiting to return after a short gap. ${state.feelings.length?`Latest expedition feeling: ${esc(state.feelings.at(-1).value)}.`:''}</p><div class="stat-grid"><div class="stat"><strong>${total}</strong><small>Skill questions completed</small></div><div class="stat"><strong>${practised}/${playableSkills.length}</strong><small>Skills explored</small></div><div class="stat"><strong>${total?Math.round(independent/total*100)+'%':'—'}</strong><small>Independent correct</small></div></div><div class="mastery-list">${playableSkills.map(s=>{const p=progress(s.id),st=tierStats(p,p.tier);return `<div class="mastery-item"><div class="line"><span>${esc(s.title)}</span><span>${p.attempts?`Challenge ${p.tier}/4 · ${Math.min(10,st.attempts)}/10`:'Not yet explored'}</span></div><div class="bar"><div style="width:${Math.min(st.attempts*10,100)}%"></div></div><p class="tiny muted">${st.recentIndependent} of ${st.recentCount} recent questions solved independently</p></div>`}).join('')}</div><hr class="separator"><button class="alt-btn" data-action="export">Export progress JSON</button><button class="text-button" data-action="reset">Reset V4 progress</button></section></div><section class="panel" style="margin-top:20px"><h2>Curriculum map · KS1–KS3</h2><p class="small muted">${skills.length} mapped micro-skills; ${playableSkills.length} actually have working question generators. Other skills are a development roadmap, not playable content.</p>${stages.map(st=>`<details class="curriculum-section"><summary>${esc(st.label)} · ${st.band}</summary><div class="curriculum-items">${skills.filter(s=>s.stage===st.id).map(s=>`<span>${s.playable?'✓':'○'} ${esc(s.title)}</span>`).join('')}</div></details>`).join('')}</section><div class="notice">Local prototype only: no server, authentication, analytics or automatic syncing. Parent controls are not PIN-protected. A public release should be reviewed for accessibility and children's data protection.</div>`;}
function setParent(){const n=document.querySelector('#parent-name')?.value?.trim();if(n)state.name=n.slice(0,24);state.preferredSkill=document.querySelector('#parent-skill')?.value||state.preferredSkill;state.manualTier=document.querySelector('#parent-tier')?.value||state.manualTier;state.goal=Number(document.querySelector('#parent-goal')?.value??state.goal);state.missionPreference=document.querySelector('#parent-preference')?.value||state.missionPreference;if(state.manualTier!=='auto'){const t=Number(state.manualTier),p=progress(state.preferredSkill);p.unlockedTier=Math.max(p.unlockedTier,t);p.tier=t;p.parentPlaced=true;state.progress[state.preferredSkill]=p;state.selectedTiers[state.preferredSkill]=t;}save();}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'});}
function toast(message){const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),2400);}
function exportState(){const a=document.createElement('a'),blob=new Blob([JSON.stringify({version:4.2,exported:new Date().toISOString(),progress:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);a.href=url;a.download='dinomath-v4.2-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,skill,zone:z,tier,index,value,filter,preset}=el.dataset;
 if(action==='dismiss'){state.pendingRewards.shift();syncRewardQueue();if(!rewardPopup)showRewardModal=false;save();render();}
 else if(action==='see-reward'){showRewardModal=true;render();}
 else if(action==='close-rewards'){showRewardModal=false;render();}
 else if(action==='home'){screen='home';render();scrollTop();}
 else if(action==='zone'){zone=z||zone;screen='zone';render();scrollTop();}
 else if(action==='parent'){screen='parent';render();scrollTop();}
 else if(action==='quiet'){state.quiet=!state.quiet;save();render();}
 else if(action==='journal'){screen='journal';render();scrollTop();}
 else if(action==='museum'){screen='museum';state.museum=sanitiseMuseum(state.museum);museumMessage='';museumSelected='';render();scrollTop();}
 else if(action==='museum-species'){if(museumSpecies.some(d=>d.key===el.dataset.species)){museumDino=el.dataset.species;museumSelected='';museumMessage='';museumMistakes=0;render();scrollTop();}}
 else if(action==='museum-length'){museumModel=Math.max(1,Math.min(4,Number(value)||2));render();}
 else if(action==='museum-factor'){museumFactor=Math.max(2,Math.min(5,Number(value)||3));render();}
 else if(action==='museum-pick'){if(museumParts.some(p=>p.id===el.dataset.part)){museumSelected=el.dataset.part;museumMessage='Choose a numbered place on the skeleton.';render();}}
 else if(action==='museum-place'){const species=museumSpecies.find(d=>d.key===museumDino);const part=el.dataset.part;const m=state.museum[museumDino]||emptyExhibit();if(!museumSelected){museumMessage='Pick a bone card first, then try a position.';}else if(part===museumSelected&&canPlace(m,part)){m.pieces.push(part);m.completed=m.pieces.length===museumParts.length;state.museum[museumDino]=m;museumMessage=m.completed?`Excellent — you assembled ${species.title}!`: `That fits! ${museumParts.find(p=>p.id===part)?.name} placed. Where does the next piece belong?`;museumSelected='';museumMistakes=0;save();}else{museumMistakes++;const p=museumParts.find(p=>p.id===museumSelected);museumMessage=`Not quite. ${p?.clue||'Look at the outline and try another spot.'}${museumMistakes>=2?' Try the position clues below if you like.':''}`;}render();}
 else if(action==='museum-hint'){const p=museumParts.find(x=>x.id===museumSelected);const sp=museumSpecies.find(x=>x.key===museumDino);museumMessage=p?(p.id==='feature'?sp.featureClue:p.clue):'Choose a bone card and I’ll help you look for its place.';render();}
 else if(action==='museum-catalogue'){catalogueMuseumItem(el.dataset.item,'Fossil');}
 else if(action==='museum-equip'){catalogueMuseumItem(el.dataset.item,'Equipment');}
 else if(action==='filter'){journalFilter=filter||'All';journalVisible=12;render();}
 else if(action==='journal-more'){journalVisible+=12;render();}
 else if(action==='dig'){digTiles=new Set();digFinds=0;screen='dig';render();scrollTop();}
 else if(action==='brush'){const i=Number(index);if(!digTiles.has(i)){digTiles.add(i);if([1,4,7,10].includes(i)){digFinds++;state.fossils++;if(state.fossils===1||state.fossils%4===0){const item=researchRewardAt(state.researchFinds++);queueReward(item,'Excavation find!','find');}}save();render();}}
 else if(action==='dig-reset'){digTiles=new Set();digFinds=0;render();}
 else if(action==='start'){startMission(skill);}
 else if(action==='route'){startTrail(z||skillById[skill||state.preferredSkill]?.zone||'ridge',skill);}
 else if(action==='workshop'){openWorkshop(z||skillById[skillId]?.zone||'ridge');}
 else if(action==='lab-back'){screen=workshopBack;render();scrollTop();}
 else if(action.startsWith('lab-')){labModel=adjustModel(workshopZone,action,labModel.a,labModel.b);render();}
 else if(action==='feeling'){const v=value;if(['easy','okay','hard'].includes(v)){state.feelings=state.feelings.filter(f=>f.visit!==visitSerial);state.feelings.push({visit:visitSerial,value:v,at:Date.now()});state.feelings=state.feelings.slice(-50);save();render();}}
 else if(action==='choose-tier'){const p=progress(skill),t=Number(tier);if(t<=p.unlockedTier){state.selectedTiers[skill]=t;save();render();}}
 else if(action==='select'){if(feedback)return;selected=value;render();}
 else if(action==='step'){if(feedback)return;const d=Number(el.dataset.delta)||0;const v=q.visual;const lim=Math.max(5,Math.abs(v.start),Math.abs(v.end))+2;selected=String(Math.max(-Math.min(65,lim),Math.min(Math.min(65,lim),Number(selected)+d)));interacted=true;render();}
 else if(action==='denom'){if(feedback)return;selected=`0/${Number(value)}`;interacted=true;render();}
 else if(action==='fill'){if(feedback)return;selected=`${Number(value)}/${Number(selected.split('/')[1])}`;interacted=true;render();}
 else if(action==='order-pick'){const chosen=selected?selected.split('|'):[];if(!chosen.includes(value)&&chosen.length<q.tokens.length){selected=[...chosen,value].join('|');feedback='';render();}}
 else if(action==='order-clear'){selected='';feedback='';render();}
 else if(action==='hint'){hint=!hint;render();}
 else if(action==='check'){evaluate();}
 else if(action==='show'){showAnswer();}
 else if(action==='skip'){skipQuestion();}
 else if(action==='gentle'){if(q?.tier>1){state.selectedTiers[skillId]=q.tier-1;state.manualTier='auto';save();skipQuestion();}}
 else if(action==='next'){if(state.goal&&sessionDone>=state.goal)screen='end';else nextQuestion();render();scrollTop();}
 else if(action==='end'){screen='end';render();scrollTop();}
 else if(action==='save-settings'){setParent();render();toast('Settings saved on this device');}
 else if(action==='focus'){setParent();if(state.missionPreference==='trail')startTrail(skillById[state.preferredSkill]?.zone||'ridge',state.preferredSkill);else startMission(state.preferredSkill);}
 else if(action==='preset'){setParent();state.preferredSkill=({young:'count.to20',middle:'fractions.add',advanced:'number.signed'})[preset];state.manualTier='auto';if(preset==='advanced'){const p=progress('number.signed');p.unlockedTier=Math.max(p.unlockedTier,2);p.tier=Math.max(p.tier,2);p.parentPlaced=true;state.progress['number.signed']=p;state.selectedTiers['number.signed']=2;}save();render();toast('Starting skill selected');}
 else if(action==='export'){exportState();}
 else if(action==='reset'){if(confirm('Reset DinoMath progress saved in this browser? This cannot be undone unless you have a backup.')){state=defaults();syncRewardQueue();showRewardModal=false;save();screen='parent';render();}}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-math-input]')){selected=e.target.value;const btn=document.querySelector('[data-action="check"]');if(btn)btn.disabled=!selected.trim();}else if(e.target.matches('[data-slider]')){selected=e.target.value;interacted=true;const label=document.getElementById('lift-value');if(label)label.textContent=fmt(selected);const btn=document.querySelector('[data-action="check"]');if(btn)btn.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-math-input]')){e.preventDefault();evaluate();}if(e.key==='Escape'&&rewardPopup){showRewardModal=false;render();}});
render();
